-- Optional company-level PT slabs. Explicit salary overrides retain priority.
create function payroll_private.pt_slab(monthly_gross numeric) returns numeric language sql immutable strict set search_path='' as $$select case when monthly_gross<=15000 then 0 when monthly_gross<=20000 then 150 else 200 end::numeric$$;
revoke all on function payroll_private.pt_slab(numeric) from public,anon,authenticated;
do $patch$ declare src text; begin src=pg_get_functiondef('payroll_private.calculate(uuid,date)'::regprocedure);
 if (length(src)-length(replace(src,'monthly_pt=coalesce((select v.pt_override from public.payroll_salaries v where v.staff_id=s.id and v.effective_from<=least(last_day,coalesce(s.leaving_date,last_day)) order by v.effective_from desc limit 1),p.pt,0);','')))/length('monthly_pt=coalesce((select v.pt_override from public.payroll_salaries v where v.staff_id=s.id and v.effective_from<=least(last_day,coalesce(s.leaving_date,last_day)) order by v.effective_from desc limit 1),p.pt,0);')<>1 then raise exception 'PT function changed; review required';end if;
 execute replace(src,'monthly_pt=coalesce((select v.pt_override from public.payroll_salaries v where v.staff_id=s.id and v.effective_from<=least(last_day,coalesce(s.leaving_date,last_day)) order by v.effective_from desc limit 1),p.pt,0);','monthly_pt=coalesce((select v.pt_override from public.payroll_salaries v where v.staff_id=s.id and v.effective_from<=least(last_day,coalesce(s.leaving_date,last_day)) order by v.effective_from desc limit 1),case when coalesce((c.settings->>''pt_auto_slabs'')::boolean,false) and month_start>=nullif(c.settings->>''pt_effective_from'','''')::date then payroll_private.pt_slab(gross) else p.pt end,0);');end $patch$;
do $patch$ declare src text; begin src=pg_get_functiondef('payroll_private.dispatch(text,jsonb)'::regprocedure);
 if (length(src)-length(replace(src,'j=payload->''settings'';','')))/length('j=payload->''settings'';')<>1 then raise exception 'PT function changed; review required';end if;
 execute replace(src,'j=payload->''settings'';','j=payload->''settings'';
  if j ? ''pt_auto_slabs'' and coalesce(j->>''pt_auto_slabs'','''') not in (''true'',''false'') then raise exception ''Invalid PT slab setting'';end if;
  if coalesce((j->>''pt_auto_slabs'')::boolean,false) and (nullif(j->>''pt_effective_from'','''') is null or (j->>''pt_effective_from'')::date<>date_trunc(''month'',(j->>''pt_effective_from'')::date)::date) then raise exception ''Select the first day of the PT policy month'';end if;');end $patch$;
notify pgrst,'reload schema';
